<file_change path="qa/tests/route-claims.test.mts" language="typescript" change_type="new" encoding="text">
import { describe, expect, it } from 'vitest'
import { readFileSync, readdirSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

// Card 97583327. `features/browser-use.md` used to assert that the browser-only
// recording/script routes were "mirrored under /api/computers", while the
// `/api/computers` route table listed no such row. Every check that existed at
// the time passed on it: `ignoreDeadLinks: true`, the nav/sidebar checks and the
// reachability checks say nothing about whether a cited route exists at all.
//
// The route tables are the only published route inventory this repo has (the
// FastAPI app lives outside this root, so `api/` is not readable from here).
// These assertions therefore treat a table row as the proof that a route exists
// and fail when prose cites a route - or a second prefix - that no table lists.

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..')
const FEATURES_DIR = join(ROOT, 'features')

/**
 * Pages whose prose is checked against the route tables. Deliberately only the
 * two co-desktop pages that make route claims: a page is added here after its
 * routes have been hand-checked, otherwise this stays a real check instead of a
 * growing list of exceptions.
 */
const ROUTE_CLAIM_PAGES = ['features/browser-use.md', 'features/computer-use.md']

/** Wording that asserts a route (family) is also served under a second prefix. */
const MIRROR_CLAIM =
  /\b(mirrored under|also available under|also served under|also mounted under|equivalent under)\b/i

/**
 * Route citations that are genuine prose claims but have no table row (yet).
 * A route that IS in a table must not stay in here - the stale-entry assertion
 * below fails - so this cannot rot into a silent allowlist.
 */
const KNOWN_UNDOCUMENTED_CITATIONS: Record<string, string> = {
  'features/browser-use.md /api/browsers/*/control':
    'the co-browsing protocol cites POST /api/browsers/{id}/control while the browser route table has no /control row (the computer table has one); add the row, then delete this entry.',
}

const PARAM_SEGMENT = /^(\{[^}]*\}|:[A-Za-z0-9_]+|<[^>]*>|\[[^\]]*\])$/

function featurePages(): string[] {
  return readdirSync(FEATURES_DIR)
    .filter((name) => name.endsWith('.md'))
    .map((name) => `features/${name}`)
    .sort()
}

function readPage(page: string): string[] {
  return readFileSync(join(ROOT, page), 'utf8').split('\n')
}

/** `/api/x/{id}/y?z` -> `/api/x/*/y`: query, anchor and trailing punctuation dropped. */
function normaliseRoute(raw: string): string {
  const clean = raw.split('#')[0].split('?')[0].replace(/[.,;:)\]]+$/, '')
  const segments = clean.split('/').filter((segment) => segment !== '')
  return `/${segments.map((segment) => (PARAM_SEGMENT.test(segment) ? '*' : segment)).join('/')}`
}

function segmentsOf(path: string): string[] {
  return normaliseRoute(path).split('/').filter((segment) => segment !== '')
}

/** Backticked `/api/...` paths on one markdown line. */
function apiTokens(line: string): string[] {
  const tokens: string[] = []
  for (const match of line.matchAll(/`([^`]*\/api\/[^`]*)`/g)) {
    const start = match[1].indexOf('/api/')
    if (start < 0) continue
    const token = match[1].slice(start).split(/\s/)[0]
    if (token.length > '/api/'.length) tokens.push(token)
  }
  return tokens
}

/** The published route inventory: `/api/...` paths inside markdown table rows. */
function documentedRoutes(): Map<string, string> {
  const routes = new Map<string, string>()
  for (const page of featurePages()) {
    readPage(page).forEach((line, index) => {
      if (!line.trim().startsWith('|')) return
      for (const token of apiTokens(line)) {
        const key = normaliseRoute(token)
        if (!routes.has(key)) routes.set(key, `${page}:${index + 1}`)
      }
    })
  }
  return routes
}

function samePrefix(row: string[], citation: string[]): boolean {
  return row.every((segment, index) => segment === '*' || segment === citation[index])
}

/**
 * A citation is backed when a table lists the same route, or lists its immediate
 * parent (`/recording` documents `/recording/start`). Anything deeper - a route
 * cited under a prefix whose table only has the prefix root - is unbacked, which
 * is exactly the shape of the defect this file guards.
 */
function isBacked(citation: string[], documented: Map<string, string>): boolean {
  for (const key of documented.keys()) {
    const row = key.split('/').filter((segment) => segment !== '')
    if (row.length === citation.length && samePrefix(row, citation)) return true
    if (row.length === citation.length - 1 && samePrefix(row, citation)) return true
  }
  return false
}

interface Citation {
  page: string
  line: number
  path: string
}

/** Backticked routes cited in a page, ignoring bare `/api/<prefix>` mentions. */
function routeCitations(page: string): Citation[] {
  const citations: Citation[] = []
  readPage(page).forEach((line, index) => {
    for (const token of apiTokens(line)) {
      const segments = segmentsOf(token)
      if (segments.length <= 2) continue // `/api/x` names a prefix, not a route
      citations.push({ page, line: index + 1, path: normaliseRoute(token) })
    }
  })
  return citations
}

/** Paragraphs (blank-line separated) with the line they start on. */
function paragraphs(page: string): { text: string; line: number }[] {
  const blocks: { text: string; line: number }[] = []
  let buffer: string[] = []
  let start = 0
  readPage(page).forEach((line, index) => {
    if (line.trim() === '') {
      if (buffer.length > 0) blocks.push({ text: buffer.join(' '), line: start + 1 })
      buffer = []
      return
    }
    if (buffer.length === 0) start = index
    buffer.push(line)
  })
  if (buffer.length > 0) blocks.push({ text: buffer.join(' '), line: start + 1 })
  return blocks
}

/** "X is mirrored under /api/y" must be backed by an /api/y row for that route. */
function unbackedMirrorClaims(documented: Map<string, string>): string[] {
  const problems: string[] = []
  for (const page of featurePages()) {
    for (const block of paragraphs(page)) {
      if (!MIRROR_CLAIM.test(block.text)) continue
      const tokens = apiTokens(block.text)
      const prefixes = tokens.filter((token) => segmentsOf(token).length === 2)
      const routes = tokens.filter((token) => segmentsOf(token).length > 2)
      for (const prefix of prefixes) {
        const prefixSegments = segmentsOf(prefix)
        for (const route of routes) {
          const routeSegments = segmentsOf(route)
          if (routeSegments[1] === prefixSegments[1]) continue // same prefix, not a mirror
          const mirrored = [...prefixSegments, ...routeSegments.slice(2)]
          if (!isBacked(mirrored, documented)) {
            problems.push(
              `${page}:${block.line} says ${route} is mirrored under ${prefix}, but no route table lists /${mirrored.join('/')}`,
            )
          }
        }
      }
    }
  }
  return problems
}

describe('T4 - route claims are backed by a published route table', () => {
  const documented = documentedRoutes()

  it('parses a route inventory (canary: an empty inventory would pass every check below)', () => {
    expect(documented.size, 'no /api route parsed out of any features/*.md table').toBeGreaterThan(30)
    const computerUse = [...documented.values()].filter((origin) =>
      origin.startsWith('features/computer-use.md'),
    )
    expect(computerUse.length, 'the /api/computers table was not parsed').toBeGreaterThan(15)
    const citations = ROUTE_CLAIM_PAGES.flatMap(routeCitations)
    expect(citations.length, 'no route citation found in the co-desktop pages').toBeGreaterThan(10)
  })

  it('no page claims a route is mirrored under a prefix whose table lacks it', () => {
    const problems = unbackedMirrorClaims(documented)
    expect(problems, `unbacked mirror claim(s): ${problems.join(' | ')}`).toEqual([])
  })

  it('browser-use.md no longer says the browser-only routes are mirrored under /api/computers', () => {
    // The regression lock for card 97583327, stated in the wording that was wrong.
    const source = readFileSync(join(ROOT, 'features/browser-use.md'), 'utf8')
    expect(source).not.toMatch(/mirrored under\s+`?\/api\/computers/)
  })

  it('every route cited in the co-desktop pages is listed in a route table or registered', () => {
    const unbacked: string[] = []
    const stale: string[] = []
    for (const citation of ROUTE_CLAIM_PAGES.flatMap(routeCitations)) {
      const key = `${citation.page} ${citation.path}`
      const backed = isBacked(segmentsOf(citation.path), documented)
      if (!backed && !(key in KNOWN_UNDOCUMENTED_CITATIONS)) {
        unbacked.push(`${key} (cited at ${citation.page}:${citation.line})`)
      }
      if (backed && key in KNOWN_UNDOCUMENTED_CITATIONS) stale.push(key)
    }
    expect(unbacked, `cited but absent from every route table: ${unbacked.join('; ')}`).toEqual([])
    expect(
      stale,
      `now documented - delete these KNOWN_UNDOCUMENTED_CITATIONS entries: ${stale.join('; ')}`,
    ).toEqual([])
  })
})
